-- Issue #836 (Phase 836, D-836-01): database backstop of the leave limit rule shape. Prisma models no CHECK
-- constraint and `prisma migrate diff` ignores one, so this file is hand-written and the CI drift guard stays
-- empty (precedent: TimeEntry_travel_shape_check, Tenant_salonQuota_positive). The application rule lives in the
-- leave-limits module and its write route; these constraints only make a malformed rule impossible for every
-- writer. The table is new, so no existing row can violate them.
--
-- Why a separate, later file than the table: the table and its enum are generated by `migrate diff` in the
-- previous migration; hand-written statements never share a file with generated ones, so a regeneration can
-- never swallow or duplicate them.

-- A limit of zero persons is a blackout; a negative limit is meaningless.
ALTER TABLE "LeaveLimitRule" ADD CONSTRAINT "LeaveLimitRule_maxPersons_check" CHECK ("maxPersons" >= 0);

-- Both bounds null = the whole year; either bound alone is an open window; both set must not be inverted.
ALTER TABLE "LeaveLimitRule" ADD CONSTRAINT "LeaveLimitRule_window_check"
  CHECK ("validFrom" IS NULL OR "validUntil" IS NULL OR "validFrom" <= "validUntil");

-- The group is exactly one of three shapes: ALL (no column), CLASSIFICATION (classification only) or
-- ACCESS_ROLE (accessRoleId only).
ALTER TABLE "LeaveLimitRule" ADD CONSTRAINT "LeaveLimitRule_group_shape_check" CHECK (
  ("groupKind" = 'ALL'            AND "classification" IS NULL     AND "accessRoleId" IS NULL) OR
  ("groupKind" = 'CLASSIFICATION' AND "classification" IS NOT NULL AND "accessRoleId" IS NULL) OR
  ("groupKind" = 'ACCESS_ROLE'    AND "accessRoleId" IS NOT NULL   AND "classification" IS NULL)
);
